from pathlib import Path
import base64, html, json
ROOT=Path(__file__).resolve().parents[1]
slides=[]
def add(ch,title,lead,body,cls='',note=''):
    slides.append(dict(ch=ch,title=title,lead=lead,body=body,cls=cls,note=note))
def cols(*items):
    return '<div class="columns">'+''.join('<div class="col">'+x+'</div>' for x in items)+'</div>'
def item(n,title,text):
    return f'<div class="item"><span class="num">{n}</span><div><h3>{title}</h3><p>{text}</p></div></div>'
def flow(*items):
    return '<div class="flow">'+''.join(f'<div class="step"><span class="step-n">{i+1:02}</span><h3>{a}</h3><p>{b}</p></div>' for i,(a,b) in enumerate(items))+'</div>'
def call(text):return '<div class="callout">'+text+'</div>'
def rows(items): return '<div class="rows">'+''.join(f'<div class="row"><h3>{a}</h3><p>{b}</p></div>' for a,b in items)+'</div>'
def big(n,t): return f'<div class="statement"><strong>{n}</strong><p>{t}</p></div>'
add('Propuesta de trabajo','QA agentizada','Más capacidad de prueba, con conocimiento compartido y evidencia.', '<div class="cover-meta">Una evolución del workbook que ya usamos<br>Para QA, Desarrollo, Negocio y gerentes</div><div class="cover-words"><span>Conocimiento</span><span>Pruebas</span><span>Mantenimiento</span></div><div class="cover-number" aria-hidden="true">QA</div>','cover', 'Propuesta de primer MVP. Las integraciones nuevas requieren validación en el entorno del equipo.')
add('01 / Propósito','Más trabajo cubierto con la capacidad disponible','El objetivo es cubrir más pruebas, o sostener la misma carga con menos dedicación del equipo.',cols(big('Capacidad','Copilot ayuda a preparar, ejecutar y documentar trabajo repetible.'),'<h3>Agentizar un proceso</h3><p>Darle a un asistente un objetivo, contexto y herramientas permitidas para realizar tareas encadenadas.</p><h3>Cómo evaluar el resultado</h3><p>Medir el trabajo aceptado, incluyendo revisión, retrabajo y mantenimiento.</p>')+call('El ahorro y los cambios de dotación son objetivos a evaluar. Todavía no son resultados demostrados.'),'light')
add('01 / Punto de partida','El workbook ya es nuestra base','Cada colaborador tiene GitHub Copilot en su PC. Ya hay instrucciones y procesos para usarlo en QA.',flow(('Diseñar casos','Copilot ayuda a transformar una necesidad en pasos y resultados esperados.'),('Ejecutar pruebas','El workbook ya usa Playwright MCP para navegar la UI web.'),('Entregar evidencia','Genera reportes y Markdown para reproducir y corregir bugs.'))+call('El equipo de automatizaciones aporta los runners y las prácticas existentes. La propuesta amplía ese trabajo.'))
add('01 / Recorrido','Un ciclo por aplicación, módulo o flujo','Podemos avanzar con pocos flujos críticos sin esperar a documentar toda la compañía.', '<div class="ribbon"><span>Conocer</span><span>Validar</span><span>Probar</span><span>Aprender</span></div>'+cols('<h3>Conocimiento</h3><p>Notas técnicas conectadas y documentación funcional revisada.</p>','<h3>Pruebas</h3><p>Casos, automatizaciones y ejecuciones con evidencia.</p>','<h3>Cambios</h3><p>Features y bugs actualizan los documentos y las pruebas relacionadas.</p>')+call('La unidad de avance es un flujo con entregables completos y una versión identificable.'),'light')
add('01 / Personas','Responsabilidades que se complementan','El agente prepara trabajo. Las personas aportan criterio y deciden lo que necesita validación.',rows([('Desarrollo','Aporta qué cambió, sus dependencias y los detalles de implementación.'),('QA y automatizaciones','Revisan cobertura y resultados, aceptan pruebas reutilizables y clasifican fallos.'),('Negocio o responsable del proceso','Confirma reglas críticas, condiciones y excepciones.'),('Responsable del conocimiento','Coordina revisión, publicación y sincronización. No reconstruye todo solo.'),('Copilot','Redacta, propone casos, ayuda a mantener pruebas y usa herramientas autorizadas.')]),'roles')
add('01 / Azure DevOps','Cada herramienta tiene una función','Boards, Test Plans, Repos y Pipelines se conectan, pero guardan cosas distintas.', '<div class="four-roles">'+''.join(f'<div><span class="role-letter">{a}</span><h3>{b}</h3><p>{c}</p></div>' for a,b,c in [('B','Boards','Trabajo, features y bugs. Relaciones y seguimiento.'),('T','Test Plans','Casos, suites y planes. Cobertura y resultados asociados.'),('R','Azure Repos','Git: historial de documentos, código y pruebas.'),('P','Pipelines','Ejecuciones repetibles, resultados y artefactos.')])+'</div>'+call('Git conserva revisiones exactas. Un runner es el programa que ejecuta las pruebas.'),'light')
add('02 / Proceso completo','Primero, una base confiable','Pasos 1 a 4. Cada etapa deja algo concreto que la siguiente puede usar.', '<div class="process-list">'+item('01','Segundo cerebro técnico','Copilot identifica fuentes, dependencias, comportamiento y dudas.')+item('02','Borrador funcional','Describe procesos y resultados. Distingue lo observado de lo inferido.')+item('03','Validación focalizada','QA, negocio o el responsable revisan las reglas críticas. Publicamos lo aprobado y mantenemos pendientes explícitos.')+item('04','Casos trazables','Copilot propone y QA revisa resultados esperados y cobertura. Vinculamos regla y caso en Test Plans y Boards.')+'</div>','process')
add('02 / Proceso completo','Después, pruebas que vuelven a servir','Pasos 5 a 8. El ciclo termina cuando el trabajo se puede repetir y mantener.', '<div class="process-list">'+item('05','Automatizaciones UI, API y base','Preparación de datos, verificaciones y herramientas autorizadas.')+item('06','Ejecución y evidencia','Guardamos resultados. Las pruebas aceptadas pasan a Pipelines.')+item('07','Reporte y seguimiento','Clasificamos los fallos y registramos defectos confirmados con sus relaciones.')+item('08','Mantenimiento por cambio','Actualizamos conocimiento, documentación, casos y automatizaciones impactadas.')+'</div>','process light')
add('03 / Conocimiento','Un segundo cerebro técnico','Notas Markdown (archivos de texto) pequeñas y conectadas que explican la aplicación y sus dependencias.', '<div class="knowledge-map"><div class="map-center"><h3>Cancelar pedido</h3><p>Proceso bajo análisis</p></div><div class="map-node n1">Código<br><small>servicio de pedidos</small></div><div class="map-node n2">Reglas<br><small>estado y excepciones</small></div><div class="map-node n3">Datos<br><small>pedido y stock</small></div><div class="map-node n4">Dependencias<br><small>reservas e inventario</small></div></div>'+call('Las notas se enlazan entre sí y con sus fuentes. Cada nota conserva el contexto necesario para leerla sola.'))
add('03 / Conocimiento','Una nota que se puede verificar','La brevedad ayuda a encontrar información. La procedencia permite confiar en ella.', '<div class="note-sheet"><div class="note-heading">cancelacion-pedido.md <span>Ejemplo ilustrativo</span></div><div class="note-grid"><div><b>Contenido</b><p>El servicio devuelve stock al cancelar un pedido pendiente.</p><b>Fuente y versión</b><p>Archivo / método + revisión Git.<br>Sistema 2.4, ambiente QA.</p><b>Relaciones</b><p>Pedido, reserva, inventario y casos asociados.</p></div><div><b>Estado de la afirmación</b><p><em>Validado</em>: confirmado por responsable.<br><em>Observado</em>: visto en código o ejecución.<br><em>Inferido</em>: hipótesis a revisar.<br><em>Pendiente</em>: falta resolver.</p><b>Validación</b><p>Rol responsable, fecha y dudas abiertas.</p></div></div></div>','light')
add('03 / Documentación','Se puede arrancar aunque falten documentos','El segundo cerebro se construye con el material y los accesos disponibles.',flow(('Reunir fuentes','Código, Swagger/OpenAPI, consultas, tickets y pruebas existentes.'),('Reconstruir comportamiento','Copilot describe qué hace el sistema y dónde encontró cada afirmación.'),('Redactar para negocio','Explica procesos, condiciones, resultados y excepciones en lenguaje funcional.'))+call('La documentación funcional nace de esa base técnica. Las inferencias quedan visibles para revisión.'))
add('03 / Documentación','Del código a una regla explicable','Ejemplo ilustrativo: la cancelación de un pedido y su efecto sobre el stock.',cols('<span class="label">Comportamiento observado</span><h3>El código devuelve stock</h3><p>Copilot encuentra una actualización de inventario cuando se cancela el pedido.</p><p>La nota enlaza el método y la versión analizada.</p>','<span class="label">Borrador funcional</span><h3>¿Cuándo corresponde?</h3><p>Describe estado permitido, precondiciones, resultado y excepciones.</p><p>Quedan dudas sobre pedidos despachados y reservas parciales.</p>')+call('El código muestra lo implementado. Un conocedor del proceso confirma qué debería pasar.'),'light')
add('03 / Validación','Revisión humana donde aporta criterio','QA, negocio o el responsable revisan borradores cortos y resuelven las dudas críticas.', '<div class="review-layout"><div class="quote">“¿Un pedido despachado puede cancelarse y devolver stock?”</div><div>'+item('1','Confirmar la regla','Alguien con conocimiento del proceso define las condiciones y excepciones.')+item('2','Aprobar la versión','La documentación registra quién validó y qué quedó pendiente.')+item('3','Usar esa referencia','Los casos toman el resultado esperado de la regla revisada.')+'</div></div>'+call('No hace falta escribir todo desde cero ni revisar manualmente cada corrida. La revisión se concentra en reglas y cambios.'))
add('03 / Incertidumbre','Cuando nadie puede confirmar una regla','El conocimiento sigue siendo útil si su estado queda claro.',cols(big('Observado','Conservamos lo que hace hoy el sistema, con fuente y versión.'),'<h3>Pruebas de caracterización</h3><p>Registran el comportamiento actual y detectan si cambia.</p><h3>Alcance del resultado</h3><p>Sirven para regresión. La corrección funcional sigue pendiente de validación.</p>')+call('Cada pendiente mantiene un responsable o un punto de resolución. La IA no convierte una observación en una regla aprobada.'),'light')
add('03 / Modelos','Separar tareas mejora la revisión','Podés usar el mismo modelo en sesiones separadas o modelos distintos para sumar perspectivas.', '<div class="model-example"><div class="percent">20<span>%</span><small>Dos modelos lo aceptan</small></div><div class="model-rule"><h3>La regla real permite 10%</h3><p>Si ambos usan una fuente equivocada, pueden repetir el mismo error.</p><p>Cambiar de modelo no garantiza independencia.</p></div></div>'+call('Separá responsabilidades y contrastá fuentes. Cada resultado esperado necesita respaldo revisado.'))
add('03 / Recuperación','El buscador devuelve fragmentos relevantes','RAG es recuperar conocimiento para darle contexto al asistente. La respuesta depende de qué fragmentos encuentra.',cols('<h3>Consulta con contexto</h3><p>Aplicación, módulo, ambiente y versión del sistema. Estado de validación y revisión del documento.</p><h3>Información completa para el caso</h3><p>Regla, precondiciones, excepciones y dependencias relacionadas.</p>','<h3>Validación en el piloto</h3><p>Probar preguntas conocidas. Revisar si aparecen los fragmentos necesarios y si corresponden a la versión elegida.</p><h3>Buscador compartido</h3><p>RAGFlow es una opción para el MVP. Confirmar la implementación y verificar metadatos y filtros en la versión instalada.</p>')+call('Recuperar un fragmento no garantiza comprender todo el proceso.'),'light')
add('03 / Publicación','Git conserva la historia del conocimiento','Azure Repos es la fuente canónica de notas técnicas y documentación funcional.',flow(('Azure Repos','Markdown con historial, responsables y revisiones exactas.'),('Publicación aprobada','Sincronización propuesta de una versión revisada, identificada por su revisión Git.'),('Buscador compartido','Indexa esa publicación y recupera fragmentos con los mismos metadatos.'))+call('Subir archivos al buscador no reemplaza el historial Git. No asumimos versionado Git nativo de RAGFlow.'))
add('04 / Casos','Dos fuentes para diseñar una prueba','La documentación funcional dice qué debe pasar. El segundo cerebro técnico ayuda a comprobarlo.', '<div class="case-inputs"><div><span class="label">Referencia funcional validada</span><h3>Resultado esperado</h3><p>“Al cancelar un pedido pendiente, se libera el stock reservado”.</p></div><div class="join">+</div><div><span class="label">Conocimiento técnico</span><h3>Cómo verificarlo</h3><p>UI o endpoint, estado del pedido, reserva e inventario.</p></div></div><div class="case-output"><h3>Caso propuesto por Copilot, revisado por QA</h3><p>Precondiciones, datos, pasos, verificaciones y cobertura de excepciones.</p></div>','light')
add('04 / Trazabilidad','La relación regla y caso empieza al diseñar','Test Plans registra los casos. Boards los vincula con el trabajo que les da origen.', '<div class="trace-chain"><div><small>Documento aprobado</small><h3>Regla R-07</h3><p>Cancelación permitida</p></div><div><small>Azure Test Plans</small><h3>Caso C-12</h3><p>Datos + esperado</p></div><div><small>Azure Repos</small><h3>Prueba A-12</h3><p>Código reutilizable</p></div><div><small>Azure Pipelines</small><h3>Corrida E-31</h3><p>Versión + evidencia</p></div></div>'+call('La feature o el bug de Boards enlaza estos elementos. QA revisa resultados esperados y cobertura antes de automatizar.'),'trace')
add('04 / Automatización','La exploración deja una prueba reutilizable','Cada exploración automatizable termina en código que el equipo puede aceptar y repetir.',cols('<div class="checkline">01 <span>Preparación de datos y ambiente</span></div><div class="checkline">02 <span>Acciones y verificaciones explícitas</span></div><div class="checkline">03 <span>Evidencia y limpieza cuando corresponda</span></div><div class="checkline">04 <span>Versionado y revisión del equipo</span></div>','<h3>Copilot crea y mantiene</h3><p>Ayuda a convertir la exploración en una automatización estable.</p><h3>El runner ejecuta</h3><p>Pipelines repite las pruebas aceptadas. La regresión no depende de una nueva exploración libre del modelo en cada corrida.</p>'),'light')
add('05 / Conexiones','Copilot y Azure DevOps MCP','MCP es una interfaz para que el asistente use herramientas y datos de un sistema.', '<div class="mcp-diagram"><div class="mcp-main"><h3>GitHub Copilot</h3><p>Cliente en modo agente</p></div><div class="mcp-bridge"><h3>Azure DevOps MCP</h3><p>Servidor oficial, local o remoto</p></div><div class="mcp-targets"><span>Boards</span><span>Test Plans</span><span>Azure Repos</span><span>Pipelines</span></div></div>'+call('Conexión propuesta. Verificar entorno/cliente, versión, autenticación, permisos y dominios habilitados. El catálogo no implica que toda operación esté disponible.')+'<p class="micro">Este es el MCP de Azure DevOps. Azure MCP para recursos cloud tiene otro alcance.</p>')
add('05 / UI web','La conexión que ya usa el workbook','Playwright MCP permite que Copilot navegue la interfaz web y ayude a explorar flujos.', '<div class="wide-path"><div><h3>Copilot</h3><p>Interpreta el caso</p></div><div><h3>Playwright MCP</h3><p>Herramientas de navegador</p></div><div><h3>UI web</h3><p>Acciones y evidencia</p></div></div>'+cols('<h3>Exploración asistida</h3><p>Recorrer el flujo, identificar controles y observar resultados.</p>','<h3>Regresión repetible</h3><p>Guardar una prueba aceptada y versionada. El runner la vuelve a ejecutar.</p>')+call('UI significa interfaz de usuario. El alcance de esta conexión es la web.'),'light')
add('05 / Tecnologías','La metodología se adapta al sistema','Conviven aplicaciones actuales y sistemas antiguos (legacy) de unos diez años. La herramienta depende de la tecnología.',rows([('Web','Reusar Playwright y las automatizaciones de navegador existentes.'),('Servicios / API','Probar endpoints y reglas con el runner o cliente de API apropiado.'),('Base de datos','Comprobar estados y efectos con consultas SELECT controladas.'),('Escritorio y otros legacy','Relevar tecnología y automatizaciones existentes. Elegir una herramienta compatible.')])+call('Priorizamos flujos críticos y regresión. Playwright para web no es una promesa de automatizar aplicaciones de escritorio.'))
add('05 / API','Swagger describe el contrato técnico','OpenAPI define puntos de acceso (endpoints), entradas y respuestas. La prueba también verifica el negocio.', '<div class="api-example"><div class="http"><strong>200</strong><span>HTTP exitoso</span><p>La solicitud respondió.<br>Eso es una señal técnica.</p></div><div class="api-assertions"><h3>Cancelar un pedido</h3><p>¿Cambió al estado correcto?</p><p>¿Se liberó el stock que correspondía?</p><p>¿Se respetaron estados prohibidos y excepciones?</p><p>¿Los valores y efectos coinciden con la regla validada?</p></div></div>'+call('API es la interfaz entre sistemas. Una respuesta exitosa no alcanza para demostrar corrección funcional.'),'light')
add('05 / Datos','Operaciones SQL con un alcance definido','SQL es el lenguaje para consultar datos. El agente elige una operación aprobada. El ejecutor conserva el SQL fijo.',flow(('Copilot solicita','consultar_estado_pedido con un identificador válido.'),('Ejecutor controlado','Valida parámetros, ambiente permitido y operación del catálogo.'),('Base responde','Conexión con lectura mínima, límites de tiempo y cantidad de resultados.'))+call('Puede ser un script o CLI, o una herramienta MCP. MCP ofrece la interfaz. Los permisos se imponen también en el ejecutor y la base.'))
add('05 / Datos','Ejemplo: consultar el estado de un pedido','La operación responde una pregunta de QA sin habilitar SQL arbitrario.', '<div class="sql-example"><div><span class="label">Solicitud del agente</span><pre>consultar_estado_pedido\n  pedido_id: 1042\n  ambiente: QA</pre><p>El ejecutor valida el identificador y el ambiente antes de consultar.</p></div><div><span class="label">SQL fijo en el ejecutor</span><pre>SELECT id, estado\nFROM pedidos\nWHERE id = :pedido_id</pre><p>El parámetro se vincula de forma segura, sin concatenar SQL.</p></div></div><div class="result-line"><b>Resultado ilustrativo</b><span>id: 1042</span><span>estado: cancelado</span></div>'+call('QA compara el estado con el esperado. Otras operaciones aprobadas pueden verificar reserva y stock.'),'light')
add('05 / Datos','El control habilita el uso del agente','El límite funciona cuando las restricciones existen fuera de la conversación.',cols('<h3>Ejecutor protegido</h3><p>El agente no modifica las operaciones aprobadas ni accede a credenciales por otra vía.</p><p>El catálogo define parámetros, ambiente, tiempos y cantidad de filas.</p>','<h3>Conexión y base</h3><p>Permisos mínimos de lectura y acceso acotado a los datos necesarios.</p><p>Si el agente puede editar el script o usar otra conexión, puede saltear el límite del catálogo.</p>')+call('Los controles permiten automatizar consultas concretas con un alcance verificable. Un prompt, por sí solo, no impone permisos.'))
add('06 / Ejecución','Una corrida que se puede repetir','Pipelines ejecuta las automatizaciones aceptadas con el runner que el equipo ya utiliza.',flow(('Fijar la corrida','Versión del sistema, ambiente, revisión de conocimiento y revisión de pruebas.'),('Preparar y ejecutar','Datos identificables y verificaciones claras. Guardar logs, trazas y resultados.'),('Conservar evidencia','Artefactos asociados a corrida, caso y prueba. Permiten investigar y reproducir.'))+call('La evidencia respalda qué pasó. La preparación de datos y las condiciones hacen posible volver a probar.'),'light')
add('06 / Resultados','Un rojo necesita diagnóstico','El reporte distingue la causa antes de registrar un defecto de producto.', '<div class="failure-types"><div><span class="failure-mark product">P</span><h3>Producto</h3><p>El sistema contradice un resultado esperado con respaldo validado.</p></div><div><span class="failure-mark env">A</span><h3>Ambiente</h3><p>Servicio caído, acceso, datos o configuración impiden evaluar el caso.</p></div><div><span class="failure-mark test">T</span><h3>Prueba</h3><p>El script, selector o preparación falla. Hay que corregir la automatización.</p></div></div>'+call('QA revisa la evidencia. Cada rojo no se convierte automáticamente en bug, y la expectativa no cambia solo para que la prueba pase.'))
add('06 / Defectos','Un bug que Desarrollo puede reproducir','El Markdown del workbook se mantiene como una salida útil. Boards registra el defecto confirmado.', '<div class="bug-report"><div class="bug-title"><span>BUG</span><h3>Cancelación conserva una reserva</h3></div><div class="bug-body"><div><b>Contexto</b><p>Versión, ambiente, datos y precondiciones.</p><b>Reproducción</b><p>Pasos mínimos, esperado respaldado y resultado observado.</p></div><div><b>Evidencia</b><p>Capturas, request/response, logs y consulta autorizada.</p><b>Relaciones</b><p>Feature, regla, caso, prueba y corrida. Responsable y seguimiento.</p></div></div></div>'+call('Copilot ayuda a redactar. QA confirma el defecto y su clasificación antes del registro.'),'light')
add('07 / Mantenimiento','El cambio empieza en Boards','Una feature registra el cambio esperado. Desarrollo aporta qué cambió y qué puede impactar.', '<div class="maintenance-line">'+item('1','Feature con contexto','Regla nueva o modificada, dependencias y versión objetivo del sistema.')+item('2','Actualización en una rama','Copilot prepara notas técnicas y borrador funcional. Desarrollo aporta la información.')+item('3','Coordinación y revisión','El responsable del conocimiento convoca a quienes validan el cambio.')+'</div>'+call('Una rama permite trabajar sin alterar la publicación vigente. El responsable coordina, pero necesita aportes del equipo.'))
add('07 / Publicación','La revisión aprueba el cambio de conocimiento','Una pull request reúne los cambios y se vincula a la feature.',flow(('Pull request','Propuesta de cambio en Azure Repos. Revisión técnica y validación funcional.'),('Integración a main','Solo contenido aprobado. Políticas de ramas, revisores y vínculos según el proceso del equipo.'),('Sincronización','El buscador recibe la misma revisión aprobada, con versión de sistema y metadatos.'))+call('PR significa propuesta de cambio para revisión. Main es la rama principal, no la versión que necesariamente está desplegada en QA.'),'light')
add('07 / Versiones','La corrida usa la versión del sistema bajo prueba','La última revisión de main puede describir una funcionalidad que todavía no llegó a QA.', '<div class="version-example"><div><small>Ejemplo ilustrativo</small><h3>Desarrollo / main</h3><strong>2.5</strong><p>Nuevo límite de descuento: 15%.<br>Documentación aprobada para 2.5.</p></div><div><small>Ambiente bajo prueba</small><h3>QA desplegado</h3><strong>2.4</strong><p>Límite vigente: 10%.<br>Usar documentación de 2.4.</p></div></div>'+call('Cada corrida fija sistema + ambiente + revisión de conocimiento/docs + revisión de pruebas. Los analistas traen esa revisión, no “latest” sin verificar.'))
add('07 / Impacto','Una regla modificada tiene relaciones','Los vínculos permiten actualizar solo los documentos y las pruebas alcanzados por el cambio.', '<div class="impact-flow"><div class="impact-origin"><h3>Feature o bug</h3><p>Cambio confirmado</p></div><div class="impact-branches"><span>Notas técnicas y documentación funcional</span><span>Casos y resultados esperados</span><span>Automatizaciones, datos y verificaciones</span><span>Publicación e índice del buscador</span></div></div>'+call('Conservamos evidencia e historial. Un fallo de prueba no autoriza cambiar una regla por cuenta propia.'),'light')
add('08 / Primer MVP','Un piloto con pocos flujos críticos','Un MVP es una primera versión acotada. Elegimos una aplicación para recorrer el ciclo completo.',cols(big('1 flujo','Idealmente, una UI o API con validación SQL del resultado.'),'<h3>Preparación concreta</h3><p>Asignar responsables reales por rol. Reusar Copilot, workbook y Azure existentes.</p><p>Comprobar entorno/cliente, permisos, ambiente y tecnología. Habilitar solo los dominios MCP necesarios.</p><p>El equipo de automatizaciones participa en la aceptación y ejecución repetible.</p>')+call('Es el primer MVP propuesto, todavía no una implementación terminada.'))
add('08 / Entregables','Qué tiene que quedar al cerrar el piloto','El producto del MVP es un flujo que el equipo pueda revisar, ejecutar y mantener.', '<div class="deliverables"><div><span>01</span><h3>Conocimiento y documento</h3><p>Versionados, con fuentes, validación y pendientes.</p></div><div><span>02</span><h3>Casos trazables</h3><p>Reglas y trabajo vinculados en Test Plans y Boards.</p></div><div><span>03</span><h3>Prueba reutilizable</h3><p>Datos, verificaciones y revisión del equipo.</p></div><div><span>04</span><h3>Ejecución y evidencia</h3><p>Runner en Pipelines y resultados investigables.</p></div><div><span>05</span><h3>Defectos confirmados</h3><p>Reproducción y seguimiento en Boards.</p></div><div><span>06</span><h3>Ciclo de mantenimiento</h3><p>Un cambio actualiza el conjunto relacionado.</p></div></div>','light')
add('08 / Medición','La capacidad se mide con trabajo aceptado','El piloto crea una línea de base. Los números se completan con evidencia real.',rows([('Tiempo total por automatización aceptada','Preparación, generación, revisión, retrabajo y mantenimiento.'),('Estabilidad','Fallos intermitentes y causas. Un fallo intermitente pasa o falla sin cambio relevante.'),('Cobertura crítica','Flujos y reglas críticas con casos y automatizaciones aceptados.'),('Defectos detectados','Defectos confirmados, evidencia y aporte al proceso de QA.'),('Recuperación de conocimiento','Fragmentos correctos, completos y de la versión elegida.')])+call('Todavía no hay una línea de base ni retorno de inversión (ROI) demostrado. Escalar depende de los resultados del piloto.'),'metrics')
add('09 / Arquitectura','Dos circuitos conectados por la versión','El conocimiento aprobado guía las pruebas. Los cambios y resultados vuelven al conocimiento.', '<div class="two-circuits"><div><span class="label">Circuito de conocimiento</span><h3>Fuentes + Copilot + personas</h3><p>Notas y documento funcional revisados</p><div class="circuit-end">Azure Repos · revisión aprobada<br>Publicación e índice del buscador</div></div><div><span class="label">Circuito de pruebas</span><h3>Copilot + herramientas permitidas</h3><p>Casos y automatizaciones aceptadas</p><div class="circuit-end">Test Plans · Pipelines · evidencia<br>Boards · seguimiento del cambio</div></div></div>'+call('En ambos circuitos: misma versión del sistema y revisiones identificadas. Arquitectura propuesta sobre herramientas existentes.'),'light')
# Integral native SVG diagram: connections use fixed orthogonal paths, labels outside paths.
def box(x,y,w,title,sub,color='aqua'):
    colors={'aqua':'#76e6d0','lime':'#d5f78a','pink':'#edb8de','white':'#f4f3f9'}
    t=title.split('|'); s=sub.split('|')
    return f'<g class="diagram-node"><rect x="{x}" y="{y}" width="{w}" height="92" rx="12" fill="#172431" stroke="{colors[color]}" stroke-opacity=".65"/><text x="{x+16}" y="{y+29}" fill="{colors[color]}" font-size="23" font-weight="650">'+''.join(f'<tspan x="{x+16}" dy="{0 if i==0 else 27}">{html.escape(a)}</tspan>' for i,a in enumerate(t))+f'</text><text x="{x+16}" y="{y+(58 if len(t)==1 else 79)}" fill="#e1e6ee" font-size="19">'+''.join(f'<tspan x="{x+16}" dy="{0 if i==0 else 24}">{html.escape(a)}</tspan>' for i,a in enumerate(s))+'</text></g>'
def path(d,color='#76e6d0',dash=''):
    return f'<path d="{d}" fill="none" stroke="{color}" stroke-width="2.4" {("stroke-dasharray="+chr(34)+dash+chr(34)) if dash else ""} marker-end="url(#arrow)"/>'
svg='<svg class="integral" viewBox="0 0 1312 445" role="img" aria-labelledby="integralTitle integralDesc"><title id="integralTitle">Sistema completo y ciclo de QA</title><desc id="integralDesc">Las fuentes alimentan un borrador de Copilot, validado por personas y aprobado en Repos. El buscador publica esa revisión. Copilot diseña casos y usa herramientas autorizadas, dejando pruebas en Repos. Pipelines ejecuta y entrega evidencia para diagnosticar. Azure DevOps MCP conecta Copilot con Test Plans, Repos, Pipelines y Boards. Boards aporta features y bugs al siguiente cambio.</desc><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="#9caab9"/></marker></defs>'
